import { describe, expect, it, vi } from "vitest";

import { fiveMinutesAgo, inFiveMinutes, makeJWT } from "./helpers.ts";

async function freshModule(): Promise<typeof import("@/core/TeacherAuth.ts")> {
  vi.resetModules();
  return import("@/core/TeacherAuth.ts");
}

describe("TeacherAuth.storeToken", () => {

  it("treats a token with a future expiry as logged in", async () => {
    const auth = await freshModule();
    auth.storeToken(makeJWT({ aud: "gallery|teacher", exp: inFiveMinutes(), sub: "t@example.com" }));
    expect(auth.amLoggedInSimple()).toBe(true);
  });

  it("treats an expired token as logged out", async () => {
    const auth = await freshModule();
    auth.storeToken(makeJWT({ aud: "gallery|teacher", exp: fiveMinutesAgo(), sub: "t@example.com" }));
    expect(auth.amLoggedInSimple()).toBe(false);
  });

  it("is logged out before any token is stored", async () => {
    const auth = await freshModule();
    expect(auth.amLoggedInSimple()).toBe(false);
  });

  it("rejects a student-scoped token", async () => {
    const auth = await freshModule();
    const token = makeJWT({ aud: "gallery|student", exp: inFiveMinutes(), sub: "42|Ana" });
    expect(() => { auth.storeToken(token); }).toThrow(/audience/i);
  });

  it("refuses to hand out a teacher ID before one has been fetched", async () => {
    const auth = await freshModule();
    expect(() => auth.getTeacherID()).toThrow();
  });

});
